def read_file(self, filename):
    """
    :raises IOError: passed from any file operations that fail.
    """
    with open(filename, 'r') as file:
        for line in file:
            line = line.strip()
            if line.startswith('#'):
                continue
            if ':' in line:
                key, value = line.split(':', 1)
                key = key.strip()
                value = value.strip()
                if key in self.pack:
                    self.pack[key].append(value)
                else:
                    self.pack[key] = [value]
            else:
                self.discarded.append(line)
    return self

