def read_file(self, filename):
    """
    :raises IOError: passed from any file operations that fail.
    """
    try:
        with open(filename, 'r') as file:
            for line in file:
                # Assuming the file contains lines with two space-separated values:
                # the first being the bit and the second being the generator and modulus
                bit, generator_modulus = line.split(' ', 1)
                self.pack[int(bit)] = eval(generator_modulus)
    except IOError:
        raise IOError("An error occurred while reading the file.")
